package ai.kstock.mobile;
import android.net.Uri;import org.json.*;
/** One explicitly confirmed encrypted daily-close rule. Never contains quantities or cost basis. */
public final class HoldingAlertRule {
 public static final String KEY="kstock.holding-alert.rule.v1";
 public static JSONObject parse(Uri uri)throws Exception{JSONObject r=new JSONObject();for(String k:new String[]{"market","symbol","exchange","expires"})r.put(k,uri.getQueryParameter(k));r.put("stop",Double.parseDouble(uri.getQueryParameter("stop")));r.put("target",Double.parseDouble(uri.getQueryParameter("target")));r.put("id",java.util.UUID.randomUUID().toString());validate(r);return r;}
 public static void validate(JSONObject r)throws Exception{String m=r.getString("market"),e=r.getString("exchange"),s=r.getString("symbol");long now=System.currentTimeMillis(),expiry=java.time.Instant.parse(r.getString("expires")).toEpochMilli();double stop=r.getDouble("stop"),target=r.getDouble("target");if(!(m.equals("KR")&&e.equals("KRX")&&s.matches("[0-9][A-Z0-9]{5}")||m.equals("US")&&e.matches("NAS|NYS|AMS")&&s.matches("[A-Z][A-Z0-9.]{0,9}"))||!Double.isFinite(stop)||!Double.isFinite(target)||stop<=0||target<=stop||expiry<=now||expiry-now>86401000)throw new Exception("RULE_INVALID");}
 public static String check(JSONObject r,JSONObject d)throws Exception{validate(r);if(!d.optBoolean("success"))return "";JSONObject i=d.getJSONObject("instrument"),strategy=d.getJSONObject("strategy");for(String k:new String[]{"market","symbol","exchange"})if(!r.getString(k).equals(i.optString(k)))return "";if(!d.optString("dataStatus").matches("OBSERVED|STORED_OBSERVATION")||!strategy.optString("action").matches("WAIT|BUY_CONDITION_MET")||java.time.Instant.parse(strategy.getString("validUntil")).toEpochMilli()<=System.currentTimeMillis())return "";double close=d.getJSONObject("quote").getDouble("close"),sma=strategy.getJSONObject("metrics").getDouble("sma20");if(!Double.isFinite(close)||!Double.isFinite(sma)||close<=0||sma<=0)return "";return close<=r.getDouble("stop")?"STOP":close>=r.getDouble("target")?"TARGET":close<sma?"TREND":"";}
 public static void selfTest(android.content.Context c)throws Exception{
  String expiry=java.time.Instant.ofEpochMilli(System.currentTimeMillis()+3600000L).toString();JSONObject r=new JSONObject().put("market","KR").put("exchange","KRX").put("symbol","005930").put("stop",90).put("target",120).put("expires",expiry);JSONObject d=new JSONObject().put("success",true).put("instrument",new JSONObject().put("market","KR").put("exchange","KRX").put("symbol","005930")).put("dataStatus","OBSERVED").put("strategy",new JSONObject().put("action","WAIT").put("validUntil",expiry).put("metrics",new JSONObject().put("sma20",100))).put("quote",new JSONObject().put("close",89));int checks=0;
  if(!check(r,d).equals("STOP"))throw new Exception("STOP");checks++;
  d.getJSONObject("quote").put("close",121);if(!check(r,d).equals("TARGET"))throw new Exception("TARGET");checks++;
  d.getJSONObject("quote").put("close",95);if(!check(r,d).equals("TREND"))throw new Exception("TREND");checks++;
  d.getJSONObject("quote").put("close",105);if(!check(r,d).isEmpty())throw new Exception("QUIET");checks++;
  d.getJSONObject("quote").put("close",89);d.getJSONObject("instrument").put("symbol","000660");if(!check(r,d).isEmpty())throw new Exception("IDENTITY");checks++;
  d.getJSONObject("instrument").put("symbol","005930");d.put("dataStatus","UNAVAILABLE");if(!check(r,d).isEmpty())throw new Exception("STALE");checks++;
  r.put("expires","2000-01-01T00:00:00Z");boolean invalid=false;try{validate(r);}catch(Exception expected){invalid=true;}if(!invalid)throw new Exception("EXPIRY");checks++;
  TokenVault vault=new TokenVault(c);String key="kstock.holding-alert.synthetic-test",value="synthetic-only-rule";try{vault.saveValue(key,value);if(!vault.read(key).equals(value)||c.getSharedPreferences("external_access_encrypted",0).getString(key,"").contains(value))throw new Exception("ENCRYPTION");checks++;}finally{vault.forget(key);}if(!vault.read(key).isEmpty())throw new Exception("DELETE");checks++;
  java.io.File file=new java.io.File(c.getExternalFilesDir(null),"holding-alert-policy-check.json");try(java.io.FileOutputStream out=new java.io.FileOutputStream(file)){out.write(new JSONObject().put("status","PASS").put("checks",checks).put("scope","SYNTHETIC_NATIVE_POLICY_AND_ISOLATED_KEYSTORE_NOT_NOTIFICATION_DELIVERY").toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 }
}
